fn solve(m: i8, d: i8) -> i8 {
    // Days in each month for a non‐leap year
    let days_in_month = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => 28,
        _ => unreachable!("month must be in 1..=12"),
    };

    // Total calendar slots used = leading empty days (d-1) + actual days
    let total_slots = (d - 1) + days_in_month;

    // Number of weeks is the ceiling of total_slots/7, i.e. (total_slots + 6) / 7
    (total_slots + 6) / 7
}

